using System.IO;
using System.Globalization;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Xml.Linq;
using Microsoft.Win32;
namespace CrateScope;
public partial class MainWindow:Window {
 public void Preview(string report){using var json=JsonDocument.Parse(File.ReadAllText(report));library=JsonSerializer.Deserialize<List<Track>>(json.RootElement.GetProperty("results"))??[];database=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(report))!,"preview-library.json");Refresh();if(library.Count>0)Tracks.SelectedItem=library[0];}
 List<Track> library=[];bool busy;string database=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CrateScopeNative","library.json");
 public MainWindow(){InitializeComponent();KeyEdit.ItemsSource=Engine.Keys;try{if(File.Exists(database))library=JsonSerializer.Deserialize<List<Track>>(File.ReadAllText(database))??[];}catch(Exception ex){MessageBox.Show("Bibliothek konnte nicht gelesen werden: "+ex.Message);database+=".recovery-"+DateTime.Now.Ticks;}Refresh();Closing+=(_,e)=>{if(busy){e.Cancel=true;MessageBox.Show("Bitte die laufende Analyse abwarten.");}};}
 void Save(){Directory.CreateDirectory(System.IO.Path.GetDirectoryName(database)!);File.WriteAllText(database+".tmp",JsonSerializer.Serialize(library));File.Move(database+".tmp",database,true);}
 void Refresh(){if(Tracks==null)return;string term=Search.Text.ToLowerInvariant();Tracks.ItemsSource=library.Where(t=>(t.Name+" "+t.Key+" "+t.Camelot).ToLowerInvariant().Contains(term)).ToList();CountLabel.Text=$"{library.Count} Tracks";Empty.Visibility=library.Count==0?Visibility.Visible:Visibility.Collapsed;}
 void Filter(object s,TextChangedEventArgs e)=>Refresh();
 async void Import(object s,RoutedEventArgs e){var dialog=new OpenFileDialog{Multiselect=true,Filter="Audio|*.wav;*.mp3;*.flac;*.aif;*.aiff;*.m4a;*.wma|Alle Dateien|*.*"};if(dialog.ShowDialog()==true)await Add(dialog.FileNames);}
 async void OnDrop(object s,DragEventArgs e){if(e.Data.GetData(DataFormats.FileDrop) is string[] files)await Add(files);}
 async Task Add(string[] files){if(busy){MessageBox.Show("Bitte den laufenden Batch abwarten.");return;}busy=true;ImportButton.IsEnabled=false;var errors=new List<string>();try{var paths=files.SelectMany(p=>Directory.Exists(p)?Directory.GetFiles(p):[p]).Distinct().Where(p=>library.All(t=>!string.Equals(t.Path,System.IO.Path.GetFullPath(p),StringComparison.OrdinalIgnoreCase))).ToArray();for(int i=0;i<paths.Length;i++){int index=i;var p=new Progress<(double,string)>(v=>{Progress.Value=100*(index+v.Item1)/paths.Length;Status.Text=$"{index+1}/{paths.Length} · {System.IO.Path.GetFileName(paths[index])} · {v.Item2}";});try{var track=await Task.Run(()=>Engine.Analyze(paths[index],(value,text)=>((IProgress<(double,string)>)p).Report((value,text))));library.Add(track);Save();Refresh();Tracks.SelectedItem=track;}catch(Exception ex){errors.Add(System.IO.Path.GetFileName(paths[i])+": "+ex.Message);}}Status.Text=$"Fertig · {library.Count} Tracks · {errors.Count} Fehler";Progress.Value=100;if(errors.Count>0)MessageBox.Show(string.Join("\n",errors),"Analysehinweise");}catch(Exception ex){MessageBox.Show(ex.Message);}finally{busy=false;ImportButton.IsEnabled=true;}}
 void SelectTrack(object s,SelectionChangedEventArgs e){if(Tracks.SelectedItem is not Track t)return;TrackTitle.Text=t.Name;Evidence.Text=t.Manual?"Manuell korrigiert":t.Evidence;Wave.Track=t;Wave.InvalidateVisual();Details.Text=$"{t.Duration:F1} s · {t.Alternatives}\nEnergy E1: {t.Energy:F1} · Eigenes Modell aus Lautheit, Impulsdichte, Helligkeit und Tempo. Cues sind Vorschläge.";KeyEdit.SelectedItem=t.Key;BpmEdit.Text=t.Bpm.ToString(CultureInfo.InvariantCulture);CueEdit.Text=string.Join("; ",t.Cues.Select(c=>c.ToString("F2",CultureInfo.InvariantCulture)));}
 void Correct(object s,RoutedEventArgs e){if(Tracks.SelectedItem is not Track t)return;try{if(!double.TryParse(BpmEdit.Text.Replace(',','.'),CultureInfo.InvariantCulture,out double bpm)||!double.IsFinite(bpm)||bpm<20||bpm>400)throw new Exception("BPM muss zwischen 20 und 400 liegen.");var cues=CueEdit.Text.Split(';',StringSplitOptions.RemoveEmptyEntries).Select(v=>double.Parse(v.Replace(',','.'),CultureInfo.InvariantCulture)).Order().ToArray();if(cues.Length>8||cues.Any(v=>!double.IsFinite(v)||v<0||v>=t.Duration))throw new Exception("Maximal 8 Cue-Zeiten innerhalb des Tracks.");if(KeyEdit.SelectedItem is string key){t.Key=key;t.Camelot=Engine.Camelot(key);}t.Bpm=bpm;t.Cues=cues;t.Manual=true;Save();Refresh();Tracks.SelectedItem=t;Evidence.Text="Manuell korrigiert";Wave.InvalidateVisual();}catch(Exception ex){MessageBox.Show(ex.Message,"Korrektur");}}
 void Export(object s,RoutedEventArgs e){var dialog=new SaveFileDialog{Filter="JSON|*.json|Rekordbox XML|*.xml|CSV|*.csv",FileName="CrateScope-export"};if(dialog.ShowDialog()!=true)return;try{using var file=new FileStream(dialog.FileName,FileMode.CreateNew);if(dialog.FilterIndex==1){JsonSerializer.Serialize(file,library,new JsonSerializerOptions{WriteIndented=true});}else if(dialog.FilterIndex==2){var collection=new XElement("COLLECTION",new XAttribute("Entries",library.Count));var playlist=new XElement("NODE",new XAttribute("Type",1),new XAttribute("Name","CrateScope"),new XAttribute("KeyType",0),new XAttribute("Entries",library.Count));int id=0;foreach(var t in library){id++;var track=new XElement("TRACK",new XAttribute("TrackID",id),new XAttribute("Name",t.Name),new XAttribute("Location",new Uri(t.Path).AbsoluteUri.Replace("file:///","file://localhost/")),new XAttribute("AverageBpm",t.Bpm.ToString(CultureInfo.InvariantCulture)),new XAttribute("Tonality",t.Key.Replace(" major","").Replace(" minor","m")));foreach(var c in t.Cues)track.Add(new XElement("POSITION_MARK",new XAttribute("Type",0),new XAttribute("Num",-1),new XAttribute("Name","CrateScope"),new XAttribute("Start",c.ToString("F3",CultureInfo.InvariantCulture))));collection.Add(track);playlist.Add(new XElement("TRACK",new XAttribute("Key",id)));}new XDocument(new XElement("DJ_PLAYLISTS",new XAttribute("Version","1.0.0"),new XElement("PRODUCT",new XAttribute("Name","CrateScope"),new XAttribute("Version","0.2"),new XAttribute("Company","Independent")),collection,new XElement("PLAYLISTS",new XElement("NODE",new XAttribute("Type",0),new XAttribute("Name","ROOT"),new XAttribute("Count",1),playlist)))).Save(file);}else{using var writer=new StreamWriter(file);writer.WriteLine("Name,Key,Camelot,BPM,Energy");foreach(var t in library)writer.WriteLine(string.Join(",",new[]{t.Name,t.Key,t.Camelot,t.Bpm.ToString(CultureInfo.InvariantCulture),t.Energy.ToString(CultureInfo.InvariantCulture)}.Select(v=>"\""+(v.StartsWith('=')||v.StartsWith('+')||v.StartsWith('-')||v.StartsWith('@')?"'":"")+v.Replace("\"","\"\"")+"\"")));}Status.Text="Export gespeichert";}catch(Exception ex){MessageBox.Show("Export nicht möglich. Existierende Dateien werden nicht überschrieben.\n"+ex.Message);}}
}
public class WaveView:FrameworkElement {
 public Track? Track {get;set;}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);var t=Track;if(t==null){dc.DrawLine(new Pen(new SolidColorBrush(Color.FromRgb(228,232,241)),1),new Point(0,ActualHeight/2),new Point(ActualWidth,ActualHeight/2));return;}var pen=new Pen(new SolidColorBrush(Color.FromRgb(114,130,186)),Math.Max(1,ActualWidth/1000));for(int i=0;i<t.Wave.Length;i++){double x=i*ActualWidth/t.Wave.Length,h=t.Wave[i]*(ActualHeight-25)/2;dc.DrawLine(pen,new Point(x,ActualHeight/2-h),new Point(x,ActualHeight/2+h));}foreach(double c in t.Cues){double x=c/t.Duration*ActualWidth;dc.DrawLine(new Pen(new SolidColorBrush(Color.FromRgb(224,165,93)),1.5),new Point(x,3),new Point(x,ActualHeight));var text=new FormattedText(c.ToString("F1")+"s",CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),10,Brushes.SlateGray,VisualTreeHelper.GetDpi(this).PixelsPerDip);dc.DrawText(text,new Point(Math.Min(x+4,Math.Max(0,ActualWidth-text.Width)),0));}}
}


